<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class GoogleMapsConnector extends AbstractConnector {public function id():string{return 'google_maps';}public function label():string{return 'Google Maps Research';}public function actions():array{return [new ConnectorAction('search_places','Research Google Maps places through the configured Apify Google Places Actor.',RiskLevel::ExternalWrite,['type'=>'object','properties'=>['searchStringsArray'=>['type'=>'array','items'=>['type'=>'string']],'locationQuery'=>['type'=>'string'],'maxCrawledPlacesPerSearch'=>['type'=>'integer']],'required'=>['searchStringsArray']])];}public function configurationSchema():array{return ['credentials'=>['api_token'=>['type'=>'password','required'=>true]],'fields'=>['actor_id'=>['type'=>'text','default'=>'compass~crawler-google-places']]];}public function test(ConnectorConnection $c):bool{try{return $this->client(['Authorization'=>'Bearer '.$this->bearer($c,'api_token')])->get('https://api.apify.com/v2/users/me')->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);$actor=(string)(($c->configuration??[])['actor_id']??'compass~crawler-google-places');$data=$this->client(['Authorization'=>'Bearer '.$this->bearer($c,'api_token')])->timeout(300)->post('https://api.apify.com/v2/actors/'.rawurlencode($actor).'/run-sync-get-dataset-items',$a)->throw()->json();return ConnectorResult::success($data);}}
